from lib import *
S = SS('k93')
F1 = [['3 个 CA', 'ca / etcd-ca / front-proxy-ca,10 年'], ['11 张叶子证书', '1 年(364d)'], ['pki/ + *.conf', 'apiserver.crt … admin.conf …'], ['EXTERNALLY MANAGED', '全是 no']]
F2 = [['apiserver.crt', 'CN=kube-apiserver,365 天'], ['SAN', 'kubernetes… / 节点名 / 10.96.0.1 / 172.18.0.3 / 127.0.0.1'], ['admin.conf', 'O=kubeadm:cluster-admins'], ['super-admin.conf', 'O=system:masters']]
F3 = [['kubelet-client-current.pem', '符号链接 → 带时间戳的文件'], ['subject', 'O=system:nodes, CN=system:node:<节点>'], ['rotateCertificates', 'true'], ['kubelet.crt', '自签,不是集群 CA 签的']]
F4 = [['kubeadm certs renew apiserver', '文件里 serial 变了'], ['不重启', '0.1 秒内 apiserver 就出示新证书'], ['容器启动时间', '没变'], ['check-expiration', '读磁盘文件']]
PANELS = [('f', 'flow', 'kubeadm PKI'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("控制面节点 /etc/kubernetes/pki 下有 ca、etcd/ca、front-proxy-ca 三套 CA 和各组件证书,/etc/kubernetes/ 下有 admin.conf、super-admin.conf、controller-manager.conf、scheduler.conf、kubelet.conf(客户端证书内嵌在里面)。kubeadm certs check-expiration:11 张叶子证书都是 364 天后过期(Oct 10, 2027),3 个 CA(ca、etcd-ca、front-proxy-ca)是 9 年(Oct 07, 2036),EXTERNALLY MANAGED 全是 no。", f=fl(F1, cur=[1], done=[0, 2, 3]), t=tl(S(1), mark=lidx(S(1), 'admin.conf  ', 'CERTIFICATE AUTHORITY'), done=lidx(S(1), '/etc/kubernetes/pki/:', '/etc/kubernetes/*.conf')), kv=KV([['CA 10 年,叶子 1 年', 'kubeadm 的默认有效期'], ['每年要续', '升级控制面时 kubeadm upgrade 会顺带续'], ['三套 CA', 'Kubernetes、etcd、聚合层各一个']], ['叶子 1 年'])),
    step("apiserver.crt:subject CN=kube-apiserver,issuer CN=kubernetes,有效期 365 天(Oct 10 07:58:13 2026 ~ Oct 10 08:03:13 2027),SAN 有 kubernetes、kubernetes.default、…、kx-main-control-plane、localhost、10.96.0.1、172.18.0.3、127.0.0.1,用途 TLS Web Server Authentication。客户端证书的 subject 决定身份:admin.conf 是 O=kubeadm:cluster-admins, CN=kubernetes-admin,super-admin.conf 是 O=system:masters, CN=kubernetes-super-admin(绕过 RBAC),controller-manager 是 CN=system:kube-controller-manager,scheduler 是 CN=system:kube-scheduler。", f=fl(F2, cur=[0, 1], done=[2, 3]), t=tl(S(2), mark=lidx(S(2), 'subject=subject=CN=kube-apiserver', 'SAN:'), done=lidx(S(2), 'admin.conf 内嵌', 'controller-manager.conf')), kv=KV([['SAN', '访问 apiserver 用的名字/IP 必须在里面'], ['O= 是组', 'system:masters 绕过 RBAC'], ['CN= 是用户名', '身份就写在证书里']], ['SAN'])),
    step("kubelet 的证书在 /var/lib/kubelet/pki:kubelet-client-current.pem 是符号链接,指向 kubelet-client-2026-10-10-08-03-14.pem,subject=O=system:nodes, CN=system:node:kx-main-control-plane,过期时间 Oct 10 2027;配置里 rotateCertificates: true(客户端证书到期前自动轮转)。kubelet.crt(用于 10250 端口的服务证书)是自签的,issuer 是 kx-main-control-plane-ca@…,不是集群 CA 签的;serverTLSBootstrap 未设置。", f=fl(F3, cur=[0, 2], done=[1], mark=[3]), t=tl(S(3), mark=lidx(S(3), 'kubelet-client-current.pem', 'rotateCertificates'), done=lidx(S(3), 'kubelet.crt(serving)')), kv=KV([['轮转', 'kubelet 客户端证书自动续,靠 CSR(见 k21)'], ['serving 证书', '默认自签,metrics-server 才需要 --kubelet-insecure-tls'], ['serverTLSBootstrap', '开了之后 serving 证书也走 CSR']], ['轮转'])),
    step("kubeadm certs renew apiserver:磁盘上的 apiserver.crt 立刻换成新的(serial 从 3EA9911F6D50D107 变成 5A98A8B813D8C969,notBefore 比当前时间早 5 分钟,是 kubeadm 为容忍时钟偏差回拨的);不重启 apiserver,0.1 秒就发现 apiserver 对外出示的证书已经是新的了——容器没有重启(同一个容器,启动时间仍是 18:01:12),说明 apiserver 会自动重新加载服务证书文件。kubeadm certs check-expiration 里 apiserver 一行变成 Oct 10, 2027 18:01 UTC,它读的是磁盘上的文件,不是进程里的。", f=fl(F4, cur=[1], done=[0, 2, 3]), t=tl(S(4), mark=lidx(S(4), 'kubeadm certs renew', '不重启 apiserver'), done=lidx(S(4), 'check-expiration', 'kubectl 访问正常')), kv=KV([['服务证书热加载', 'apiserver 的 --tls-cert-file 变化后自动生效'], ['客户端证书', 'etcd / kubelet 客户端证书是否热加载本文未验证'], ['renew 要在每个控制面节点做', '证书是各节点本地文件']], ['服务证书热加载'])),
]
A = mkartk('k93', 93, 'Kubernetes,kubeadm,证书,PKI,CA,证书续期,真实验证,动画演示',
    '在 kind 控制面节点上读 kubeadm 的 PKI:3 套 CA 有效期 10 年、11 张叶子证书 1 年(364d);apiserver.crt 的 SAN 包含 kubernetes.default…、节点名、10.96.0.1、172.18.0.3、127.0.0.1;admin.conf 是 O=kubeadm:cluster-admins,super-admin.conf 是 O=system:masters;kubelet 客户端证书靠 rotateCertificates 自动轮转,serving 证书自签;kubeadm certs renew apiserver 之后不重启 apiserver 它就在 0.1 秒内出示新证书。',
    'kubeadm 集群里有哪些证书、各自多久过期?apiserver 的证书里写了什么?admin.conf 和 super-admin.conf 差在哪?续期之后要不要重启 apiserver?这篇在控制面节点里用 openssl 逐张读证书,再真的续一次期并观察 apiserver 对外出示的证书。',
    [('364d / 9y', '叶子证书与 CA 在 kubeadm 默认配置下的剩余有效期'), ('O=system:masters', 'super-admin.conf 的证书组——绕过 RBAC;admin.conf 是 O=kubeadm:cluster-admins'), ('0.1 秒', 'kubeadm certs renew apiserver 之后,不重启 apiserver 就对外出示新证书所用的时间')],
    [('有哪些证书', '<p>控制面节点 <code>/etc/kubernetes/pki</code> 下有 <code>ca</code>、<code>etcd/ca</code>、<code>front-proxy-ca</code> 三套 CA 和各组件证书;<code>/etc/kubernetes/</code> 下的 <code>admin.conf</code>、<code>super-admin.conf</code>、<code>controller-manager.conf</code>、<code>scheduler.conf</code>、<code>kubelet.conf</code> 把客户端证书内嵌在里面。<code>kubeadm certs check-expiration</code>:11 张叶子证书都是 364 天后过期(Oct 10, 2027),3 个 CA 是 9 年(Oct 07, 2036),<code>EXTERNALLY MANAGED</code> 全是 no。</p>'),
     ('证书里写了什么', '<p><code>apiserver.crt</code>:<code>subject CN=kube-apiserver</code>,<code>issuer CN=kubernetes</code>,有效期 365 天,SAN 有 <code>kubernetes</code>、<code>kubernetes.default</code>、<code>kubernetes.default.svc</code>、<code>kubernetes.default.svc.cluster.local</code>、<code>kx-main-control-plane</code>、<code>localhost</code>、<code>10.96.0.1</code>、<code>172.18.0.3</code>、<code>127.0.0.1</code>,用途是 TLS Web Server Authentication。客户端证书的 subject 就是身份:<code>admin.conf</code> 是 <code>O=kubeadm:cluster-admins, CN=kubernetes-admin</code>(靠 RBAC 绑定 cluster-admin),<code>super-admin.conf</code> 是 <code>O=system:masters, CN=kubernetes-super-admin</code>(<code>system:masters</code> 组绕过 RBAC),controller-manager、scheduler 分别是 <code>CN=system:kube-controller-manager</code>、<code>CN=system:kube-scheduler</code>。</p>'),
     ('kubelet 的证书', '<p><code>/var/lib/kubelet/pki/</code> 下 <code>kubelet-client-current.pem</code> 是符号链接,指向带时间戳的 <code>kubelet-client-2026-10-10-08-03-14.pem</code>,subject 是 <code>O=system:nodes, CN=system:node:kx-main-control-plane</code>;配置里 <code>rotateCertificates: true</code>,到期前会自动轮转(靠 CSR,见 k21)。<code>kubelet.crt</code>(10250 端口的服务证书)是自签的,issuer 是 <code>kx-main-control-plane-ca@…</code>,不是集群 CA 签的;<code>serverTLSBootstrap</code> 没设置。</p>'),
     ('续期要重启吗', '<p><code>kubeadm certs renew apiserver</code> 后,磁盘上的 <code>apiserver.crt</code> 立刻变成新的(serial 从 <code>3EA9911F6D50D107</code> 变为 <code>5A98A8B813D8C969</code>;<code>notBefore</code> 比当前时间早 5 分钟,这是 kubeadm 为容忍时钟偏差回拨的)。不重启 apiserver,0.1 秒就发现它对外出示的证书已经是新的——容器没有重启(同一个容器,启动时间不变),说明 apiserver 会自动重新加载服务证书文件。<code>kubeadm certs check-expiration</code> 里 apiserver 一行随之变成 <code>Oct 10, 2027 18:01 UTC</code>;它读的是磁盘文件,不是进程里的状态。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(Kubernetes v1.37.0,kubeadm 创建)的控制面节点,用 docker exec 运行 kubeadm certs check-expiration 与 openssl;apiserver 出示的证书用 openssl s_client 连 127.0.0.1:6443 取得;只续了 apiserver 这一张(其余证书保持原状);“0.1 秒”是第一次轮询时就已经一致,实际切换时间不会超过这个量级;每种情形各一次',
     '没有验证:apiserver-etcd-client / apiserver-kubelet-client 等客户端证书是否也能热加载;kubeadm certs renew all 后 controller-manager、scheduler 是否需要重启(它们的证书内嵌在 .conf 里);外部 CA 模式;过期后的恢复流程;kubeadm upgrade 自动续期;多控制面节点上逐个续期;证书到期前 kubelet 的告警;serverTLSBootstrap 开启后的 CSR 审批'],
    'kubeadm 证书', PANELS)
